if(!exists('build_payment_history_features'))library(creditratingsystem)
local({
 date<-'2024-01-05';coverage<-function(status='COMPLETE')list(status=status,known_at=date,observed_from='2024-01-01',complete_through=date);obligation<-list(obligation_id='one',account_id='a',due_at='2024-01-02',known_at='2024-01-01',amount=100,currency='EUR');payment<-function(id,amount,date,kind='payment',reverse=NULL,known=date)list(payment_id=id,account_id='a',paid_at=date,known_at=known,amount=amount,currency='EUR',kind=kind,reverses_payment_id=reverse);history<-function(pays=list(),grace=0,obs=list(obligation),cov=coverage())build_payment_history_features(obs,pays,cov,'a',date,date,4,'fifo','EUR',grace)
 r<-history(list(payment('p',40,'2024-01-02'),payment('r',40,'2024-01-03','reversal','p',known='2024-01-04')))$value;stopifnot(identical(vapply(r$daily_history,`[[`,numeric(1),'unpaid_due_amount'),c(60,60,100,100)),identical(vapply(r$daily_history,`[[`,numeric(1),'dpd'),c(0,1,2,3)),r$features$mean_dpd==1.5,r$features$arrears_days==3,r$assessments[[1]]$payment_ratio==.4,r$features$partial_payment_count==1)
 r<-history(list(payment('pre',60,'2024-01-01'),payment('due',40,'2024-01-02')))$value;stopifnot(r$features$full_payment_count==1,r$features$max_dpd==0,r$features$assessment_payment_ratio==1)
 r<-history(list(payment('p',100,'2024-01-04')),2)$value;stopifnot(identical(vapply(r$daily_history,`[[`,numeric(1),'dpd'),c(0,1,0,0)),r$assessments[[1]]$assessment_at=='2024-01-04',r$assessments[[1]]$due_at=='2024-01-02');stopifnot(history(grace=10)$value$not_assessable[[1]]$reason=='GRACE_NOT_ELAPSED')
 r<-history(obs=list(),cov=coverage('UNKNOWN'))$value;stopifnot(is.null(r$features$max_dpd),r$known_history_features$max_dpd==0)
 balance<-function(d,amount=100,limit=200,activity='ACTIVE')list(snapshot_id=d,release_seq=1,account_id='a',observed_at=d,known_at=d,balance=amount,credit_limit=limit,activity_status=activity,currency='EUR');revolving<-function(rows,statements=list())build_revolving_features(rows,statements,coverage(),'a',date,date,4,'EUR');r<-revolving(list(balance('2024-01-02'),balance('2024-01-03',limit=100),balance('2024-01-04',limit=80),balance(date,limit=80)))$value;change<-r$balance_changes[[1]];stopifnot(r$overlimit_days==2,r$missing_days==0,change$balance_change==0,change$limit_change== -100,change$utilization_change==.5,change$balance_effect_at_new_limit==0,change$limit_effect_on_previous_balance==.5,r$utilization_endpoint_trend_per_day==.25)
 r<-revolving(list(balance(date,0,0)))$value;stopifnot(is.null(r$latest_snapshot$utilization),r$latest_snapshot$undrawn_active,is.null(r$overlimit_days),r$missing_days==3,!revolving(list(balance(date,0,0,'INACTIVE')))$value$latest_snapshot$undrawn_active)
 statement<-function(id,paid)list(statement_id=id,release_seq=1,account_id='a',issued_at='2024-01-01',due_at='2024-01-03',observed_at='2024-01-04',known_at='2024-01-04',statement_balance=100,minimum_due=10,paid_by_due=paid,currency='EUR');r<-revolving(list(),list(statement('min',10),statement('full',100),statement('below',5)))$value;stopifnot(r$full_payer_count==1,r$minimum_without_full_count==1,r$below_minimum_count==1)
 bad<-balance(date);bad$snapshot_id<-'other';stopifnot(inherits(tryCatch(revolving(list(balance(date),bad)),error=function(e)e),'error'))
})
